"""Generate distribution notices from installed locked dependencies; not a rights opinion."""
from pathlib import Path
import json,re
from importlib.metadata import distribution
ROOT=Path(__file__).resolve().parents[1]
lock=json.loads((ROOT/'frontend/package-lock.json').read_text(encoding='utf-8'))
table=['# Dependency and asset notices','','Generated from the locked versions and locally installed license files. Metadata is evidence, not a warranty or legal clearance. Preserve upstream notices when distributing bundles.','','## Frontend installed production/build dependencies','','| Package | Version | Declared license | Installed notice |','|---|---|---|---|']
notices=['LunaRIDGE frontend third-party notices','Application code rights are separate. The following upstream license texts retain their original terms.','']
for name,info in sorted(lock['packages'].items()):
    if not name or info.get('dev'):continue
    directory=ROOT/'frontend'/name
    if not directory.exists():continue # optional binaries for other platforms are not shipped
    pkg=json.loads((directory/'package.json').read_text(encoding='utf-8'));label=pkg.get('name',name);license=pkg.get('license','UNDECLARED')
    if isinstance(license,dict):license=license.get('type',str(license))
    files=[p for p in directory.iterdir() if p.is_file() and re.match(r'^(LICENSE|COPYING|NOTICE)(\.|$)',p.name,re.I)]
    table.append(f"| {label} | {info['version']} | {license} | {'yes' if files else 'review upstream'} |")
    for path in files:notices.extend([f'\n--- {label} {info["version"]}: {path.name} ---\n',path.read_text(encoding='utf-8',errors='replace')])
(ROOT/'frontend/public/third-party-notices.txt').write_text('\n'.join(notices),encoding='utf-8')
table.extend(['','## Backend production dependencies','','Full installed notices: [Python third-party licenses](THIRD_PARTY_PYTHON_LICENSES.txt).','','| Package | Version | Declared license |','|---|---|---|'])
notices=['LunaRIDGE backend third-party distribution notices','']
for name,version in re.findall(r'^([A-Za-z0-9_.-]+)==([^\s;]+)',(ROOT/'backend/requirements.lock').read_text(encoding='utf-8'),re.M):
    dist=distribution(name);lic=dist.metadata.get('License-Expression') or dist.metadata.get('License') or 'UNDECLARED'
    if len(lic)>100:lic='see full installed notice'
    table.append(f'| {name} | {version} | {lic.replace(chr(10)," ").replace("|","/")} |')
    for path in dist.files or []:
        if re.search(r'(^|/)(licenses?/|copying|notice|license)',str(path),re.I) and dist.locate_file(path).is_file():
            try:body=dist.locate_file(path).read_text(encoding='utf-8')
            except UnicodeError:continue
            notices.extend([f'\n--- {name} {version}: {Path(path).name} ---\n',body])
(ROOT/'docs/THIRD_PARTY_PYTHON_LICENSES.txt').write_text('\n'.join(notices),encoding='utf-8')
table.extend(['','## First-party source and images','','No application code license is assigned. The owner must confirm source/contributor rights before an OSI license can responsibly be recommended. Dependency licenses do not license LunaRIDGE source. NASA data terms are separate; see [DATA_SOURCES.md](DATA_SOURCES.md).','','- `frontend/public/lunar_south_pole_dem.png`: generated from the verified LOLA DEM by `backend/generate_lunar_map.py`; regenerated byte-for-byte during Step 16A. SHA-256 `e59b966c4ab107f4abd20413a7752f690235b3157bacc7f6eeaa47f74a830f7f`. NASA LRO/LOLA, GSFC PGDA and Barker et al. credits apply. This is synthetic hillshade/color relief, not actual scenario sunlight.','- `frontend/public/lunaridge-mark.svg`: original primitive SVG created during Step 16A; not a NASA insignia. Application licensing remains pending.','- Unused `hero.png`, React/Vite starter images are excluded by Git ignore. Unverified unused public SVGs and the old favicon were moved to ignored `checkpoints/step16a-assets/`. No invented redistribution permission.','- Lucide React icons: ISC license; upstream notice is included in the generated frontend notices.','- Google-hosted Plus Jakarta Sans and JetBrains Mono are requested at runtime with system fallbacks; no font binary is vendored. Both upstream font repositories carry SIL Open Font License 1.1: [Plus Jakarta Sans](https://github.com/tokotype/PlusJakartaSans/blob/master/OFL.txt), [JetBrains Mono](https://github.com/JetBrains/JetBrainsMono/blob/master/OFL.txt). Browser requests to Google are a third-party privacy/availability consideration.','','The static release includes [frontend third-party notices](../frontend/public/third-party-notices.txt). Re-run `python scripts/dependency_notices.py` after changing dependency locks and review any `review upstream` or `UNDECLARED` entries. Do not describe all dependencies or NASA products as covered by the eventual application code license.'])
(ROOT/'docs/THIRD_PARTY_NOTICES.md').write_text('\n'.join(table)+'\n',encoding='utf-8')
